shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ece6d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c1b1;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --crimson: #8f2822;
    --navy-bg: #0f1d2b;
    --navy-card: #17283a;
    --navy-line: #293e54;
    --gold: #d49b4b;
    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-serif: 'Lora', 'Noto Serif SC', Georgia, serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--font-serif);
    font-size: 16px;
    line-height: 1.75;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    overflow-x: hidden;
    background-color: var(--paper);
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line-strong);
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0.7rem 1.5rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-monogram {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .brand-sep {
    width: 1px;
    height: 14px;
    background: var(--line-strong);
  }

  .section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 600;
  }

  .page-folio {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
    background: var(--paper-card);
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.3rem 0.65rem;
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.18s ease;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Section */
  .hero-header {
    max-width: 1120px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 3px double var(--line-strong);
  }

  .kicker-row {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--accent);
    font-weight: 700;
  }

  .kicker-dot {
    width: 7px;
    height: 7px;
    background: var(--accent);
    border-radius: 50%;
    display: inline-block;
  }

  .hero-title {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: clamp(2.1rem, 4.4vw, 3.65rem);
    line-height: 1.16;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.25rem;
    max-width: 960px;
  }

  .hero-dek {
    font-family: var(--font-serif);
    font-size: clamp(1.12rem, 1.8vw, 1.38rem);
    line-height: 1.55;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 2rem;
    font-weight: 400;
  }

  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--muted);
  }

  .byline-names {
    color: var(--ink);
    font-weight: 600;
  }

  .dateline {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--muted);
  }

  /* Main Container & Asymmetric Forensic Rails */
  .editorial-shell {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 4rem;
  }

  /* Reporter Context Dossier */
  .context-dossier {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--ink);
    padding: 1.4rem 1.75rem;
    margin-bottom: 3rem;
    position: relative;
  }

  .dossier-badge {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.5rem;
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .dossier-text {
    font-family: var(--font-sans);
    font-size: 0.94rem;
    line-height: 1.7;
    color: var(--body);
  }

  /* Two-Column Forensic Rail Layout */
  .forensic-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.85fr) minmax(280px, 1fr);
    gap: 3rem;
    align-items: start;
    margin-bottom: 3rem;
  }

  .prose-column {
    min-width: 0;
  }

  .rail-column {
    min-width: 0;
    position: sticky;
    top: 4.5rem;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
  }

  /* Prose Styling */
  .prose-p {
    font-family: var(--font-serif);
    font-size: 1.12rem;
    line-height: 1.88;
    color: var(--body);
    margin-bottom: 1.45rem;
  }

  :host([lang="zh-CN"]) .prose-p {
    line-height: 1.92;
    letter-spacing: 0.01em;
  }

  .lead-p {
    font-size: 1.24rem;
    line-height: 1.78;
    color: var(--ink);
    font-weight: 600;
    padding-left: 1.15rem;
    border-left: 3px solid var(--accent);
    margin-bottom: 1.65rem;
  }

  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 0.12em;
    font-weight: 600;
  }

  /* Chapter Dividers */
  .chapter-break {
    margin: 3.2rem 0 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--line-strong);
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 1rem;
    flex-wrap: wrap;
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    font-weight: 700;
  }

  .chapter-title {
    font-family: var(--font-display);
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
    width: 100%;
    margin-top: 0.25rem;
  }

  /* Sidebar Forensic Dossier Cards */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem;
  }

  .card-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.45rem;
  }

  .card-heading {
    font-family: var(--font-display);
    font-size: 1.12rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.9rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--line);
  }

  .personnel-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.95rem;
  }

  .personnel-item {
    padding-bottom: 0.9rem;
    border-bottom: 1px dashed var(--line-strong);
  }

  .personnel-item:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .person-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.25rem;
  }

  .person-name {
    font-family: var(--font-sans);
    font-weight: 700;
    font-size: 0.92rem;
    color: var(--ink);
  }

  .status-pill {
    font-family: var(--font-mono);
    font-size: 0.66rem;
    font-weight: 700;
    text-transform: uppercase;
    padding: 0.12rem 0.45rem;
    border-radius: 2px;
    background: rgba(143, 40, 34, 0.12);
    color: var(--crimson);
    white-space: nowrap;
  }

  .status-pill.warn {
    background: rgba(184, 93, 25, 0.15);
    color: var(--accent);
  }

  .person-role {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Bespoke Full-Bleed Architectural SVG Box */
  .architecture-showcase {
    background: var(--navy-bg);
    color: #f4f1ea;
    padding: 2.4rem 2rem;
    margin: 3rem 0;
    border: 1px solid var(--navy-line);
    border-top: 4px solid var(--gold);
  }

  .arch-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.6rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--navy-line);
  }

  .arch-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 0.35rem;
  }

  .arch-title {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 700;
    color: #ffffff;
  }

  .arch-subtitle {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    color: #b0becd;
    max-width: 560px;
  }

  .svg-frame {
    width: 100%;
    overflow: hidden;
  }

  .svg-frame svg {
    width: 100%;
    height: auto;
    display: block;
  }

  /* Split Callout Box for Key Admission or Clash */
  .admission-callout {
    background: var(--paper-card);
    border-left: 4px solid var(--crimson);
    padding: 1.35rem 1.5rem;
    margin: 1.65rem 0;
  }

  .admission-label {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--crimson);
    font-weight: 700;
    margin-bottom: 0.45rem;
  }

  .admission-callout .prose-p {
    margin-bottom: 0;
    font-size: 1.08rem;
    font-weight: 600;
    color: var(--ink);
  }

  /* Grand Jury Friction Card */
  .friction-box {
    background: var(--paper-deep);
    border: 1px solid var(--line-strong);
    padding: 1.25rem;
  }

  .friction-step {
    display: flex;
    gap: 0.75rem;
    margin-bottom: 0.85rem;
    align-items: flex-start;
  }

  .friction-step:last-child {
    margin-bottom: 0;
  }

  .step-num {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--paper);
    background: var(--ink);
    width: 22px;
    height: 22px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    margin-top: 0.15rem;
  }

  .step-body {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    line-height: 1.5;
    color: var(--body);
  }

  /* Climactic Final Verdict Box */
  .verdict-dossier {
    margin-top: 2.2rem;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.75rem 2rem;
  }

  .verdict-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    font-weight: 700;
    margin-bottom: 0.65rem;
  }

  .verdict-quote {
    margin-top: 1rem;
    padding-top: 1rem;
    border-top: 1px dashed var(--line-strong);
    font-family: var(--font-serif);
    font-size: 1.14rem;
    line-height: 1.85;
    color: var(--ink);
    font-weight: 600;
  }

  /* Footer */
  .article-footer {
    max-width: 1120px;
    margin: 0 auto;
    padding: 2rem 1.5rem 4rem;
    border-top: 1px solid var(--line-strong);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 860px) {
    .forensic-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }

    .rail-column {
      position: static;
    }

    .hero-header {
      padding: 2.2rem 1.15rem 1.75rem;
    }

    .editorial-shell {
      padding: 1.75rem 1.15rem 3rem;
    }

    .architecture-showcase {
      padding: 1.5rem 1rem;
      margin: 2rem 0;
    }

    .verdict-dossier {
      padding: 1.35rem 1.15rem;
    }
  }
